import sqlalchemy

def get_newest_posts(cursor, category, column):
    query = "SELECT * FROM posts WHERE category = '%s' ORDER BY %s DESC LIMIT 10;" % (category, column)
    cursor.execute(query)
    return cursor.fetchall()

