import mysql.connector
from mysql.connector import Error
import logging

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def get_employee_threshold_db_config():
    # Configuration for database connection
    return {
        'user': 'your_username',
        'password': 'your_password',
        'host': 'your_host',
        'database': 'your_database'
    }

def convert_threshold_to_int(threshold):
    try:
        return int(threshold)
    except ValueError:
        logger.error("Threshold must be an integer")
        raise

def get_employees_above_threshold(threshold):
    db_config = get_employee_threshold_db_config()
    try:
        conn = mysql.connector.connect(**db_config)
        cursor = conn.cursor()
        threshold = convert_threshold_to_int(threshold)
        query = "SELECT * FROM employees WHERE salary > %s"
        cursor.execute(query, (threshold,))
        employees = cursor.fetchall()
        cursor.close()
        conn.close()
        return employees
    except Error as e:
        logger.error(f"Error getting employees: {e}")
        raise

def get_threshold():
    query = "SELECT threshold FROM config WHERE name = 'salary_threshold'"
    db_config = get_employee_threshold_db_config()
    try:
        conn = mysql.connector.connect(**db_config)
        cursor = conn.cursor()
        cursor.execute(query)
        result = cursor.fetchone()
        cursor.close()
        conn.close()
        if result:
            return result[0]
        else:
            logger.error("Threshold not found in database")
            raise
    except Error as e:
        logger.error(f"Error getting threshold: {e}")
        raise

def main():
    threshold = get_threshold()
    try:
        employees = get_employees_above_threshold(threshold)
        for employee in employees:
            print(employee)
    except Exception as e:
        logger.error(f"Error processing threshold: {e}")

import sqlite3
import logging
from urllib.parse import parse_qs

def reset_failed_login(conn, query_string):
    params = parse_qs(query_string)
    account_name = params.get('account_name', [None])[0]

    if account_name is None:
        return 'Missing account name'

    cursor = conn.cursor()
    cursor.execute('SELECT * FROM accounts WHERE name = %s' % account_name)
    result = cursor.fetchone()

    if result is None:
        return 'Account not found'

    cursor.execute('UPDATE accounts SET failed_logins = 0 WHERE name = %s' % account_name)
    conn.commit()

    return 'Failed login counter reset'

def handle_request(request):
    query_string = request.GET.get('account_name')
    if query_string is not None:
        return reset_failed_login(request.conn, query_string)
    return 'Invalid request'

def handle_json_body(request):
    if request.json:
        return reset_failed_login(request.conn, request.json['account_name'])
    return 'Invalid request'

def handle_url_path(request):
    path = request.path.strip('/')
    return reset_failed_login(request.conn, 'account_name=' + path)

def handle_form_field(request):
    form = request.form
    if form.get('account_name'):
        return reset_failed_login(request.conn, 'account_name=' + form['account_name'])
    return 'Invalid request'

